using System;

namespace StdbModule;

public static partial class PolishQuotes
{
    public static class BolesławPrus
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Sądzić by można, że na tym świecie radość nie ginie nigdy. Tylko gdy w jednym sercu zaćmiewa się, w innym zapala.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Ten, który ucieka, nie czuje smutku opuszczonych.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Biada orłom w menażerii, szczęśliwe gęsi w kojcu!", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Czy znowu grozi mi ciężka choroba?... Bo skąd ten niepokój, co za osobliwe przywidzenia?... Takich ciekawości doznawać musi pisklę, kiedy rosną mu skrzydła; takie niepokoje czuć musi na wiosnę konwalia, kiedy jej gałązki zaczynają okrywać się pączkami.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Ludzie z każdym postępują tak samo: zabierają mu pieniądze, czas, pracę, piękność, rozum, serce, nawet dobre imię... Wszystko mu zabiorą, jeżeli nie obroni go własny egoizm... Dlatego umiarkowany egoizm jest siłą dobroczynną (...).", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "– O charakterze człowieka nie stanowi to, co odziedziczył, tylko co zrobił i robi.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Przypatrz się robakom ziemnym. Nie ma stworzeń bardziej upośledzonych; a jednak one więcej robią dla cywilizacji aniżeli zdobywcy świata; w ciszy i poniżeniu wytwarzają grunta urodzajne. Sława żadna, zyski żadne, użyteczność – niezmienna.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Ludzie zawsze smucą się lub cieszą i nie ma takiej godziny, gdzie by ktoś nie śmiał się lub nie wzdychał. Cały zaś bieg historii polega na tym, że gdy więcej jest radości między ludźmi, mówimy – państwo kwitnie, a gdy częściej płyną łzy, nazywamy to upadkiem.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Miłość potrzebuje swobody i czasu do wydania najpiękniejszych plonów.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Rozkosze są niby fale i szczyty gór cierpienia – niby głębie i wąwozy i dopiero wszystkie one razem sprawiają, że życie jest piękne, gdyż rzeźbi się jak poszarpany łańcuch gór wschodnich, na które patrzymy z podziwem.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Sam się obraża, kto rozmawia z pijakiem.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Słowo (…) jest jak kamień rzucony z procy; gdy trafi na ścianę, odbije się i zwróci przeciw tobie samemu.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Więcej znaczy odważny rozum aniżeli siła.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "W czasie bitwy los co chwila wyciąga do nas rękę i każe jak najspieszniej odgadywać zamknięte w niej niespodzianki. Mylimy się lub zgadujemy, ale biada temu, kto częściej omylił się aniżeli odgadł!… A stokroć biada tym przeciw komu los odwraca się i zmusza do omyłek!…", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "W rządzie i wojnie na nikogo nie liczy się: o jeden niedopatrzony kamyk można się przewrócić.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Zgryzota jest jak skarb dany do przechowania. Póki strzeżemy jej sami, nawet sen ucieka od nas i dopiero wtedy robi się lżej, gdy znajdziemy drugiego stróża.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Człowiek miewa w życiu takie chwile, że lubi otaczać się przedmiotami, które przypominają smutek.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Dziś patrząc na starą kamizelkę widzę, że nad jej ściągaczami pracowały dwie osoby. Pan – co dzień posuwał sprzączkę, ażeby uspokoić żonę, a pani co dzień – skracała pasek, aby mężowi dodać otuchy.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Któż jednak powie, że za tymi chmurami nie ma słońca?", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Gdyby nas nawet setkami tysięcy topiono, wbijano na pale, obdzierano ze skóry, pieczono na wolnym ogniu – w całej ''sympatycznej'' Europie nikt palcem nie ruszy, nikt nie otrząśnie popiołu z cygara.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "W ''Dziadach'' kobiety posiadają jakieś nadziemskie rysy, w ''Weselu'' każda ma ochotę i kwalifikuje się… do stodoły.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Wszystko, co z Zachodu, automatycznie uważa się za lepsze. Cielęta noszą cudzoziemskie imiona, na produktach polskich nakleja się obcojęzyczne etykiety.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Dziwna bowiem jest natura ludzka: im mniej sami mamy skłonności do męczeństwa, tym natarczywiej żądamy go od innych.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Litość jest to uczucie równie przykre dla ofiarowującego, jak i dla przyjmującego.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Życie, którego początku nie pamiętamy, a końca nie znamy.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Każdy pogląd ma w sobie coś prawdy i coś fałszu, i dlatego ludzie spierają się.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Komu nóż wbijają w serce, ten nie pyta, czy innych spotkało to samo, ale woła, że boli!…", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Komu Pan Jezus miłosierny naznaczył śmierć, umrze i tak, a komu – życie, temu i wojna nie da rady.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Rozsądek, przepowiadający klęskę, jest, jak puszczyk na cmentarzu, który woła: „Nie wstaniesz!…” Taki głos jest zawsze nienawistny. A im dokładniej spełni się przepowiednia, tem większa niechęć do proroka…", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Słaba głowa, słabe serce i pycha, to najniebezpieczniejszy rodzaj ludzi.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Świat nie pyta, cośmy mówili – ale czyśmy zapobiegli nieszczęściu.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Na koniec (…), nie wierz temu, aby życie ludzkie mogło być choć przez tydzień pasmem spokoju i zadowolenia.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Najkrzykliwsi przyczynę złego widzą tylko w nieprzyjęciu nowych prawd, odkrytych w laboratoriach (…), choć złe tylko w części leży tam, a cała jego siła tkwi w zapomnieniu prawd małych, starych jak świat, a ukrytych w duszy ludzkiej (…).", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Bo, panowie, myślmy najpierw o tym, ażeby podźwignąć nasz nieszczęśliwy kraj.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Bywają wielkie zbrodnie na świecie, ale chyba największą jest zabić miłość.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Doświadczony żeglarz nie walczy z prądem ani z wiatrem, ale pozwala im się unosić w obranym przez siebie kierunku.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Dziś trzeba coś znaczyć w świecie: trzeba być użytecznym, być siłą. Inaczej świat nas nie dojrzy, nie zatroszczy się, choćby z nas darto pasy, bo świat pochłonięty jest zdobywaniem dobrobytu i cywilizacji i rachuje się tylko z tymi czynnikami, które mu pomagają.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Głupstwo jest wielkie jak morze, wszystko w sobie pomieści.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Jedna bitwa szerzej otwiera nam oczy, niż dziesiątki lat spokojnych rządów.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Każdemu łatwiej we własnym przekonaniu kierować państwem lub armią niż jednokonną biedką.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Każdy biały anioł jest w dziesiątej części prostytutką.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Łotr będzie łotrem, choćby skończył dwa fakultety.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Mała irytacja pobudza apetyt.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Mądrość każe raczej przewidywać złe niż dobre.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Miłość jest jak miód, ze smakiem można jej kosztować, ale niepodobna kąpać się w niej.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Miłość jest radością świata, słońcem życia, wesołą melodią na pustyni.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Na świecie jest coraz mniej dobrych subiektów i rozumnych polityków, bo wszyscy stosują się do mody.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Najciężej w życiu ma ten, kto usiłuje unikać trudności.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Nie myśl o szczęściu. Nie przyjdzie – nie zrobi zawodu; przyjdzie – zrobi niespodziankę.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Nie wiem, co ze mną zrobisz, Panie, ale cokolwiek zrobisz, lepsze będzie od moich teorii.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Pamiętniki robią na mnie wrażenie, jakby ktoś pisał do siebie samego i opowiadał sobie samemu wiadomości o sobie samym.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Pozwólmy ludziom być szczęśliwymi według ich własnego uznania.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Praca rozumna i wytrwała, która nie myśli o zbieraniu owoców w tydzień po posiewie, przebija góry, nad przepaściami przerzuca mosty.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Prawdziwy patriotyzm nie tylko polega na tym, ażeby kochać jakąś idealną ojczyznę, ale – ażeby kochać, badać i pracować dla realnych składników tej ojczyzny, którymi są ziemia, społeczeństwo, ludzie i wszelkie ich bogactwa.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Sądzić powinna tylko chłodna głowa, nigdy gorące serce.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Świat podobny jest do amatorskiego teatru, więc nieprzyzwoicie jest pchać się w nim do ról pierwszych, a odrzucać podrzędne. Wreszcie, każda rola jest dobra, byle grać ją z artyzmem i nie brać jej zbyt poważnie.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "To, o czym u nas nie marzył Mickiewicz,<br />to zdobyła pani Ćwierczakiewicz.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "W chwili nieszczęścia, kiedy go wszystko zdradziło, jeszcze pozostała mu wierną – ziemia, prosty człowiek i Bóg.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "W każdym mieszka i dobro, i zło, i tylko to drugie jest aktywne.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Wino robi człowieka przezroczystym.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Ze wszystkich stron mrok nas otacza.", Author = "Bolesław Prus" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Bolesław_Prus", Text = "Złodzieje są mniej niepewni od ludzi, którzy nie wiadomo skąd czerpią dochody.", Author = "Bolesław Prus" },
        };
    }
}